import{_ as a,o as t,c as r,a5 as l}from"./chunks/framework.BF53ZjCA.js";const u=JSON.parse('{"title":"蛋面与雕刻","description":"","frontmatter":{"title":"蛋面与雕刻","cutting":"cabochon-and-carving"},"headers":[],"relativePath":"zh/cutting/cabochon-and-carving.md","filePath":"zh/cutting/cabochon-and-carving.md","lastUpdated":1790876393000}'),n={name:"zh/cutting/cabochon-and-carving.md"};function i(s,e,o,d,c,h){return t(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="蛋面与雕刻" tabindex="-1">蛋面与雕刻 <a class="header-anchor" href="#蛋面与雕刻" aria-label="Permalink to &quot;蛋面与雕刻&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>当透明度、包裹体、耐久性或特殊光学效应更适合弧面时，宝石常采用蛋面 （凸圆打磨）或雕刻；这不是对所有材料的绝对限制。蛋面可突出星光、 猫眼、月光等现象，玉石与玛瑙也常见雕刻路线。</p><aside class="gem-identification-boundary" aria-labelledby="identification-boundary-cabochon-and-carving-zh"><p class="gem-identification-boundary__eyebrow">CUTTING BOUNDARY</p><h2 id="identification-boundary-cabochon-and-carving-zh">边界与安全</h2><p>本页用于理解蛋面、雕刻与光学效应之间的关系，不替代对弧面高度、曲率、包裹体 方向、裂隙和抛光状态的实物检查；特殊效应与耐久性应由专业人员复核。 </p></aside><h2 id="案例流程" tabindex="-1">案例流程 <a class="header-anchor" href="#案例流程" aria-label="Permalink to &quot;案例流程&quot;">​</a></h2><blockquote><p>教学案例（演示）：以下用于记录蛋面路线的观察逻辑，不替代实物定向和加工。</p></blockquote><h3 id="_1-确认为什么选择弧面" tabindex="-1">1. 确认为什么选择弧面 <a class="header-anchor" href="#_1-确认为什么选择弧面" aria-label="Permalink to &quot;1. 确认为什么选择弧面&quot;">​</a></h3><p>说明是透明度、包裹体、耐久性还是星光/猫眼等现象推动了蛋面方案；如果只是因为“更容易切”， 不能直接当作充分理由。</p><h3 id="_2-找到现象方向" tabindex="-1">2. 找到现象方向 <a class="header-anchor" href="#_2-找到现象方向" aria-label="Permalink to &quot;2. 找到现象方向&quot;">​</a></h3><p>在不同方向和光线下记录针状包裹体或光带的方向、连续性与强弱，标出需要让弧顶对准的区域； 方向不确定时不做确定性承诺。</p><h3 id="_3-比较弧面方案" tabindex="-1">3. 比较弧面方案 <a class="header-anchor" href="#_3-比较弧面方案" aria-label="Permalink to &quot;3. 比较弧面方案&quot;">​</a></h3><p>比较单蛋面/双蛋面、弧面高度、曲率连续性和底部稳定性，记录光带宽度、亮度、均匀性以及 可能的薄弱区域。结果需要在统一光源下复核。</p><h3 id="_4-停止条件" tabindex="-1">4. 停止条件 <a class="header-anchor" href="#_4-停止条件" aria-label="Permalink to &quot;4. 停止条件&quot;">​</a></h3><p>如果包裹体方向、裂隙、弧面连续性或抛光状态无法确认，停止将样品命名为“星光”或“猫眼”， 转为候选现象记录并寻求专业复核。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>单蛋面/双蛋面 (single/double cabochon) 描述蛋面的底部形态；星光与猫眼的清晰度还取决于弧面高度、曲率、包裹体方向与抛光质量。</li><li>星光效应需定向打磨——使金红石针平行台面。</li><li>猫眼效应同理，针状包裹体需定向于弧面轴线。</li><li>玉石雕刻（翡翠、软玉、绿松石）考验材料纹理与色彩层次运用。</li><li>蛋面高度、弧面连续性与抛光质量共同影响光带宽度、亮度和均匀性。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>切工</th><th>备注</th></tr></thead><tbody><tr><td>红宝石</td><td>星光蛋面</td><td>六射星光示例</td></tr><tr><td>虎眼石</td><td>猫眼蛋面</td><td>猫眼效应示例</td></tr><tr><td>翡翠</td><td>雕刻挂坠</td><td>雕刻路线示例</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">参考依据与证据边界</h2><p class="gem-reference-block__intro">本页内容用于学习与检索；来源用于说明知识依据，不代表仅凭本页即可完成具体样品鉴定。</p><ul><li><a href="https://www.gia.edu/gia-news-research-value-factors-gem-cutting-styles-definitions" target="_blank" rel="noreferrer">GIA：宝石切工风格定义</a><span>轮廓、刻面排列、阶梯式、蛋面与雕刻等切工风格的定义</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gia-news-research/value-factors-design-cut-quality-colored-gemstone-value-factors" target="_blank" rel="noreferrer">GIA：有色宝石价值要素与切工质量</a><span>比例、对称性、抛光、原石限制与视觉表现之间的切工取舍</span><small>打开来源 ↗</small></li><li><a href="https://4cs.gia.edu/en-us/diamond-cut/" target="_blank" rel="noreferrer">GIA：钻石切工与明亮度</a><span>圆明亮式的台面、冠部、腰棱、亭部，以及 57/58 面计数说明</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/emerald-quality-factor" target="_blank" rel="noreferrer">GIA：祖母绿质量要素</a><span>有色宝石切割对颜色、耐久性、包裹体与裂隙的综合考量</span><small>打开来源 ↗</small></li></ul></aside><aside class="gem-reference-block gem-evidence-ledger" aria-labelledby="gem-evidence-title-cabochon-and-carving-zh"><p class="gem-reference-block__eyebrow">EVIDENCE MAP</p><h2 id="gem-evidence-title-cabochon-and-carving-zh">本页证据映射</h2><p class="gem-reference-block__intro">把本页的教学主张映射到来源，并标注它在知识库中的证据状态。</p><ul><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--source-supported">来源支持</strong><span>蛋面与雕刻是常见的成品形态路线，适用性取决于材料和设计目标。</span><small>GIA：宝石切工风格定义；GIA：有色宝石价值要素与切工质量</small></li><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--teaching-summary">教学归纳</strong><span>星光、猫眼等现象的呈现需要综合考虑包裹体方向、弧面形态与抛光。</span><small>GIA：有色宝石价值要素与切工质量；GIA：宝石切工风格定义</small></li><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--teaching-summary">教学归纳</strong><span>教学案例把现象方向、弧面设计与停止条件串成可复核记录。</span><small>GIA：宝石切工风格定义；GIA：有色宝石价值要素与切工质量</small></li></ul></aside><p><em>详见<a href="./intro.html">切割总览</a>。</em></p>',21)])])}const m=a(n,[["render",i]]);export{u as __pageData,m as default};
